101	/// The `..` in `#[func(..)]`.
102	pub struct Meta {
103	    /// Whether this function has an associated scope defined by the `#[scope]` macro.
104	    pub scope: bool,
105	    /// Whether this function is contextual.
106	    pub contextual: bool,
